#include <stdio.h>
#include <string.h>
#include <ctype.h>

void toUpperCase(char s[]) {
    for (int i = 0; s[i] != '\0'; i++) {
        s[i] = toupper(s[i]);
    }
}

void toLowerCase(char s[]) {
    for (int i = 0; s[i] != '\0'; i++) {
        s[i] = tolower(s[i]);
    }
}

int countWords(char s[]) {
    int words = 0, inWord = 0;
    for (int i = 0; s[i] != '\0'; i++) {
        if (isspace(s[i])) {
            inWord = 0;
        } else if (!inWord) {
            inWord = 1;
            words++;
        }
    }
    return words;
}

int main() {
    char text[100];

    printf("Type a line: ");
    fgets(text, sizeof(text), stdin);
    text[strcspn(text, "\n")] = '\0';

    printf("Words: %d\n", countWords(text));
    printf("Letters and symbols: %zu\n", strlen(text));

    toUpperCase(text);
    printf("UPPER: %s\n", text);

    toLowerCase(text);
    printf("lower: %s\n", text);
    return 0;
}

